/**
 * PyPath trail map: scroll progress draws each segment's line and lights its stops.
 *
 * The trail is a list of segments, one <svg class="path-map" data-segment> per
 * course, stacked in one sticky viewport and generated by scripts/build-trail.mjs.
 * Each segment declares its scroll budget (data-span, in viewport heights) and the
 * seam after it (data-seam), and overall progress through the track is divided
 * between them in that proportion:
 *
 *   [ segment 1 ][ seam ][ segment 2 ]
 *
 * Inside a segment, progress 0..1 draws its line and lights its stops, which are
 * placed by arc length so they sit on the line. Across a seam the maps cross-fade
 * (--seam 0..1) and the section's data-scene switches at the seam's midpoint;
 * CSS keys the scenery off data-scene. The traveller head follows the active
 * segment's line and is hidden while the maps are mid-fade, so it never flies
 * from the end of one line to the start of the next.
 */
(function () {
  const section = document.querySelector("[data-path-journey]");
  if (!section) return;

  const track = section.querySelector(".path-journey__track");
  const reduced =
    document.documentElement.classList.contains("reduced-motion") ||
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  const cards = Array.from(section.querySelectorAll("[data-stop-card]"));

  const segments = Array.from(section.querySelectorAll(".path-map[data-segment]")).map((svg) => ({
    svg,
    scene: svg.getAttribute("data-segment"),
    span: Math.max(0, Number(svg.getAttribute("data-span")) || 1),
    seam: Math.max(0, Number(svg.getAttribute("data-seam")) || 0),
    drawPath: svg.querySelector(".path-map__draw"),
    head: svg.querySelector(".path-head"),
    stops: Array.from(svg.querySelectorAll("[data-stop]")),
    /** Fraction along this segment's path (0-1) where each stop sits */
    stopAt: [],
    start: 0,
    end: 0,
  }));
  if (!segments.length) return;

  /* Divide overall progress 0..1 between segments and seams by their budgets. */
  function layout() {
    const total = segments.reduce(
      (sum, seg, i) => sum + seg.span + (i < segments.length - 1 ? seg.seam : 0),
      0
    ) || 1;
    let at = 0;
    segments.forEach((seg, i) => {
      seg.start = at / total;
      at += seg.span;
      seg.end = at / total;
      if (i < segments.length - 1) at += seg.seam;
    });
  }

  function placeStopsOnPath(seg) {
    const { drawPath, stops, stopAt } = seg;
    if (!drawPath || typeof drawPath.getTotalLength !== "function") return;
    let len = 0;
    try {
      len = drawPath.getTotalLength();
    } catch (_) {
      return;
    }
    if (!len) return;

    const count = stops.length;
    for (let i = 0; i < count; i++) {
      const t = count === 1 ? 0 : i / (count - 1);
      stopAt[i] = t;
      const pt = drawPath.getPointAtLength(t * len);
      const stop = stops[i];

      const dot = stop.querySelector(".path-stop-dot");
      const num = stop.querySelector(".path-stop-num");
      const label = stop.querySelector(".path-stop-label");

      if (dot) {
        dot.setAttribute("cx", String(pt.x));
        dot.setAttribute("cy", String(pt.y));
      }
      if (num) {
        num.setAttribute("x", String(pt.x));
        num.setAttribute("y", String(pt.y));
      }
      if (label) {
        const side = i % 2 === 0 ? 1 : -1;
        const lx = pt.x + side * 22;
        const ly = pt.y + (i % 3 === 1 ? 22 : -18);
        label.setAttribute("x", String(lx));
        label.setAttribute("y", String(ly));
        if (side < 0) label.setAttribute("text-anchor", "end");
        else label.removeAttribute("text-anchor");
      }
    }
  }

  function placeAll() {
    segments.forEach(placeStopsOnPath);
  }

  const clamp01 = (x) => Math.min(1, Math.max(0, x));

  /* Where overall progress p lands: the scene on show, each segment's own
     progress, and how far through a seam's cross-fade we are. */
  function locate(p) {
    let sceneIndex = 0;
    let seamT = 0;
    let seamIndex = -1;
    for (let i = 0; i < segments.length; i++) {
      const seg = segments[i];
      if (p >= seg.start) sceneIndex = i;
      const next = segments[i + 1];
      if (next && p > seg.end && p < next.start) {
        seamIndex = i;
        seamT = clamp01((p - seg.end) / (next.start - seg.end));
        sceneIndex = seamT < 0.5 ? i : i + 1;
      }
    }
    return { sceneIndex, seamIndex, seamT };
  }

  function setProgress(p, { lightAll = false } = {}) {
    const progress = clamp01(p);
    section.style.setProperty("--path-progress", String(progress));

    const where = locate(progress);
    const scene = segments[where.sceneIndex];
    section.setAttribute("data-scene", scene.scene);
    section.style.setProperty("--seam", String(where.seamIndex === -1 ? (where.sceneIndex > 0 ? 1 : 0) : where.seamT));
    section.classList.toggle("is-seaming", where.seamIndex !== -1);

    let activeCard = 0;
    let offset = 0;
    segments.forEach((seg, si) => {
      const width = seg.end - seg.start;
      const local = lightAll ? 1 : width > 0 ? clamp01((progress - seg.start) / width) : progress >= seg.start ? 1 : 0;
      seg.svg.style.setProperty("--path-progress", String(local));
      seg.svg.classList.toggle("is-scene", si === where.sceneIndex);
      // Each map fades out across the seam after it and in across the seam before it.
      let opacity = si === where.sceneIndex ? 1 : 0;
      if (where.seamIndex !== -1 && (si === where.seamIndex || si === where.seamIndex + 1)) {
        opacity = si === where.seamIndex ? 1 - where.seamT : where.seamT;
      }
      seg.svg.style.setProperty("--segment-opacity", String(opacity));

      const count = seg.stops.length;
      let lastLit = -1;
      for (let i = 0; i < count; i++) {
        const threshold = seg.stopAt[i] != null ? seg.stopAt[i] : count === 1 ? 0 : i / (count - 1);
        const lit = lightAll || (progress >= seg.start && local >= Math.max(0, threshold - 0.012));
        const stop = seg.stops[i];
        stop.classList.toggle("is-lit", lit);
        const dot = stop.querySelector(".path-stop-dot");
        if (dot) dot.classList.toggle("is-lit", lit);
        if (lit) lastLit = i;
      }
      if (si === where.sceneIndex) {
        activeCard = offset + Math.max(0, lastLit);
      }

      if (seg.head && seg.drawPath && typeof seg.drawPath.getTotalLength === "function") {
        const onShow = si === where.sceneIndex && where.seamIndex === -1;
        seg.head.classList.toggle("is-hidden", !onShow);
        if (onShow) {
          try {
            const len = seg.drawPath.getTotalLength();
            const pt = seg.drawPath.getPointAtLength(local * len);
            seg.head.setAttribute("transform", `translate(${pt.x}, ${pt.y})`);
          } catch (_) {
            /* path not ready */
          }
        }
      }
      offset += count;
    });

    cards.forEach((card, i) => {
      card.classList.toggle("is-active", i === activeCard);
    });
  }

  function measure() {
    if (!track) return 0;
    const rect = track.getBoundingClientRect();
    const total = track.offsetHeight - window.innerHeight;
    if (total <= 0) return 0;
    const scrolled = Math.min(Math.max(-rect.top, 0), total);
    return scrolled / total;
  }

  let ticking = false;
  function onScroll() {
    if (ticking) return;
    ticking = true;
    requestAnimationFrame(() => {
      ticking = false;
      const p = measure();
      setProgress(p, { lightAll: reduced });
      section.classList.toggle("is-active", p > 0.008 && p < 0.995);
    });
  }

  layout();
  placeAll();

  /* Reduced motion: no drawing and no fading. Every line is shown whole and
     every stop lit, and scroll switches scenes and cards in single steps
     (the CSS removes every transition), so a visitor who asked for less
     motion still reaches both courses. With one segment there is nothing to
     switch between, so it keeps the original behaviour: the whole line, every
     stop lit, the last card showing, and no scroll listener at all. */
  if (reduced) {
    section.classList.add("is-active");
    if (segments.length === 1) {
      setProgress(1, { lightAll: true });
      cards.forEach((c) => c.classList.remove("is-active"));
      if (cards.length) cards[cards.length - 1].classList.add("is-active");
      return;
    }
  }

  setProgress(reduced ? measure() : 0, { lightAll: reduced });

  // Listen on window + body: legacy site CSS sometimes makes body the scrollport
  window.addEventListener("scroll", onScroll, { passive: true });
  document.body.addEventListener("scroll", onScroll, { passive: true });
  document.documentElement.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener(
    "resize",
    () => {
      placeAll();
      onScroll();
    },
    { passive: true }
  );
  onScroll();

  window.PyPathTrail = { locate, segments, setProgress, measure };
})();
